WITH m AS MATERIALIZED (SELECT entry_id, id, n1 AS sort_key FROM "webiny_cms_search" WHERE CASE WHEN scope_id = $1 AND view = $2 THEN $6 ELSE $7 END AND ix AND (tok @> $3::text[] AND (tsv @@ $4::tsquery AND EXISTS (SELECT $8 FROM unnest(ta1) v WHERE v::text ILIKE $5))) LIMIT $9) SELECT c.total, p.entry_id, p.id, p.sort_value FROM (SELECT count(*)::int AS total FROM m) c LEFT JOIN (SELECT entry_id, id, sort_key::text AS sort_value FROM m ORDER BY sort_key DESC, entry_id DESC LIMIT $10) p ON $11
